import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
export interface TimelineEvent { id: string; title: string; description?: string; time: string; dateTime?: string; icon?: ReactNode; active?: boolean }
export function ActivityTimeline({ events, label = "Activity", className }: { events: readonly TimelineEvent[]; label?: string; className?: string }): React.JSX.Element {
  return <ol data-slot="activity-timeline" aria-label={label} className={cn("flex flex-col",className)}>{events.map((event,index)=><li key={event.id} className="relative grid grid-cols-[32px_1fr] gap-4 pb-8 last:pb-0">{index<events.length-1&&<span aria-hidden="true" className="absolute top-8 bottom-0 left-4 w-px bg-border"/>}<span aria-hidden="true" className={cn("relative grid size-8 place-items-center rounded-full border border-border",event.active?"bg-foreground text-background":"bg-background text-muted-foreground")}>{event.icon??<span className="size-1.5 rounded-full bg-current"/>}</span><div className="min-w-0 pt-1"><div className="flex flex-wrap items-baseline justify-between gap-2"><p className="text-sm font-medium">{event.title}</p><time dateTime={event.dateTime} className="font-mono text-[10px] text-muted-foreground">{event.time}</time></div>{event.description&&<p className="mt-1 text-sm leading-relaxed text-muted-foreground">{event.description}</p>}</div></li>)}</ol>;
}
